// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.junit.jupiter.api.Test;

class LmdbAdaptiveLongArrayTest {

	@Test
	void reservesExactArrayBytesAndAccountsTheTemporaryGrowthPeak() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_024, 1_024);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			LmdbAdaptiveLongArray array = LmdbAdaptiveLongArray.tryCreate(ledger, 4);

			assertThat(array).isNotNull();
			assertThat(array.length()).isEqualTo(4);
			assertThat(ledger.usedBytes()).isEqualTo(48);
			assertThat(manager.usedBytes()).isEqualTo(48);

			assertThat(array.ensureCapacity(8)).isTrue();
			assertThat(array.length()).isEqualTo(8);
			assertThat(ledger.usedBytes()).isEqualTo(80);
			assertThat(manager.usedBytes()).isEqualTo(80);
			assertThat(manager.peakUsedBytes()).isEqualTo(128);

			array.close();
			assertThat(ledger.usedBytes()).isZero();
			assertThat(manager.usedBytes()).isZero();
		}
	}

	@Test
	void refusedGrowthRetainsTheExistingArrayAndReservation() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100, 100);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			LmdbAdaptiveLongArray array = LmdbAdaptiveLongArray.tryCreate(ledger, 4);

			assertThat(array).isNotNull();
			assertThat(array.ensureCapacity(8)).isFalse();
			assertThat(array.length()).isEqualTo(4);
			assertThat(ledger.usedBytes()).isEqualTo(48);
			assertThat(manager.usedBytes()).isEqualTo(48);
			assertThat(manager.peakUsedBytes()).isEqualTo(48);

			array.close();
			assertThat(manager.usedBytes()).isZero();
		}
	}

	@Test
	void refusedInitialAdmissionDoesNotLeakAndCloseIsIdempotent() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(47, 47);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			assertThat(LmdbAdaptiveLongArray.tryCreate(ledger, 4)).isNull();
			assertThat(ledger.usedBytes()).isZero();
			assertThat(manager.usedBytes()).isZero();
		}

		LmdbQueryMemoryManager roomy = LmdbQueryMemoryManager.createForTesting(1_024, 1_024);
		try (LmdbQueryMemoryManager.QueryLedger ledger = roomy.openQuery()) {
			LmdbAdaptiveLongArray array = LmdbAdaptiveLongArray.tryCreate(ledger, 4);
			assertThat(array).isNotNull();
			array.close();
			array.close();
			assertThat(ledger.usedBytes()).isZero();
			assertThat(roomy.usedBytes()).isZero();
		}
	}
}
